    this.seconds = 0;
  }
  start() {
    setInterval(() => {
      this.seconds += 1;
      console.log(this.seconds);
    }, 1000);
  }
}
new Timer().start();
```

With the arrow function in place, `this` within the callback now correctly refers to the `Timer` instance, so `this.seconds` increments properly and logs `1, 2, 3, ...` as intended.

